return $input.all().map((item) => {
  const body = item.json.body;

  const validObject =
    body &&
    typeof body === 'object' &&
    !Array.isArray(body);

  return {
    json: validObject ? body : {},
  };
});

return $input.all().map((item) => {
  const result = item.json;
  let statusCode;

  switch (result.outcome) {
    case 'CREATED':
      statusCode = result.should_continue === true ? 202 : 422;
      break;

    case 'IDEMPOTENT_REPEAT':
      if (result.processing_status === 'INVALID') {
        statusCode = 422;
      } else if (result.processing_status === 'REVIEW_REQUIRED') {
        statusCode = 409;
      } else {
        statusCode = 200;
      }
      break;

    case 'INVALID':
    case 'INVALID_SUBMISSION_ID':
      statusCode = 422;
      break;

    case 'SUBMISSION_ID_CONFLICT':
      statusCode = 409;
      break;

    default:
      statusCode = 500;
  }

  const correlationId =
    result.correlation_id ??
    result.attempted_correlation_id ??
    null;

  return {
    json: {
      status_code: statusCode,
      response: {
        success: statusCode === 200 || statusCode === 202,
        outcome: result.outcome ?? 'UNKNOWN',
        submission_id: result.submission_id ?? null,
        submission_record_id:
          result.submission_record_id ?? null,
        correlation_id: correlationId,
        processing_status:
          result.processing_status ?? null,
        record_created:
          result.record_created ?? false,
        should_continue:
          result.should_continue ?? false,
        validation_errors:
          result.validation_errors ?? [],
        audit_event_id:
          result.audit_event_id ?? null,
      },
    },
  };
});
